CREATE OR REPLACE FUNCTION public.protect_billing_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception 'billing event audit rows cannot be deleted' using errcode = '42501';
  end if;

  if old.provider is distinct from new.provider
     or old.provider_event_id is distinct from new.provider_event_id
     or old.event_type is distinct from new.event_type
     or old.provider_account_id is distinct from new.provider_account_id
     or old.livemode is distinct from new.livemode
     or old.api_version is distinct from new.api_version
     or old.provider_created_at is distinct from new.provider_created_at
     or old.payload is distinct from new.payload
     or old.payload_sha256 is distinct from new.payload_sha256
     or old.received_at is distinct from new.received_at then
    raise exception 'billing event identity and payload are immutable' using errcode = '22000';
  end if;
  if old.account_id is not null and old.account_id is distinct from new.account_id then
    raise exception 'billing event workspace is immutable once resolved' using errcode = '22000';
  end if;
  if old.billing_subscription_id is not null
     and old.billing_subscription_id is distinct from new.billing_subscription_id then
    raise exception 'billing event subscription is immutable once resolved' using errcode = '22000';
  end if;
  if new.attempt_count < old.attempt_count then
    raise exception 'billing event attempt count cannot decrease' using errcode = '22000';
  end if;

  if new.processing_status is distinct from old.processing_status and not (
    (old.processing_status = 'received' and new.processing_status in ('processing', 'ignored'))
    or (old.processing_status = 'processing' and new.processing_status in ('processed', 'failed', 'ignored'))
    or (old.processing_status = 'failed' and new.processing_status in ('processing', 'ignored'))
  ) then
    raise exception 'invalid billing event state transition: % -> %', old.processing_status, new.processing_status
      using errcode = '22000';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_billing_event_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
begin
  if old.event_scope is distinct from new.event_scope then
    raise exception 'billing event scope is immutable' using errcode = '22000';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.queue_operational_alerts(p_recipient text, p_from text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare v_category text; v_id uuid; v_count integer; v_total integer:=0; v_text text;
begin
  if p_recipient !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(p_from)<3 then
    raise exception 'invalid alert recipient or sender';
  end if;
  perform pg_advisory_xact_lock(782321905);
  for v_category in select distinct category from public.operational_alert_findings where delivery_id is null loop
    v_id:=gen_random_uuid();
    select count(*) into v_count from public.operational_alert_findings where category=v_category and delivery_id is null;
    select string_agg(reference||' | observed='||occurred_at::text||E'\n'||detail||E'\n'||action_required||E'\nhttps://app.letsgetquoted.com'||admin_path,E'\n\n' order by detected_at,source_key)
      into v_text from (select * from public.operational_alert_findings where category=v_category and delivery_id is null order by detected_at,source_key limit 20) f;
    insert into public.operational_alert_deliveries(id,category,payload) values(v_id,v_category,
      jsonb_build_object('from',p_from,'to',jsonb_build_array(p_recipient),
        'subject','[LGQ Ops] '||upper(v_category)||': '||v_count||' failure(s) ['||left(v_id::text,8)||']',
        'text','Operational alert '||v_id||E'\nCaptured: '||clock_timestamp()||E'\n\n'||v_text||
          case when v_count>20 then E'\n\nShowing 20 of '||v_count||' records. All references are retained in operational_alert_findings under this alert ID.' else '' end||
          E'\n\nThis monitor does not charge cards, grant credits, replay webhooks or send customer messages. Resolve the source through its supported recovery path; the next scan records when it clears.'));
    update public.operational_alert_findings set delivery_id=v_id where category=v_category and delivery_id is null;
    v_total:=v_total+1;
  end loop;
  return v_total;
end $function$
